python3 - <<'PY'
import json, os, base64, inspect
import Crypto, cryptography
from Crypto.Cipher import AES
from cryptography.hazmat.primitives.asymmetric import ed25519,x25519
from cryptography.hazmat.primitives.serialization import Encoding,PublicFormat
print('PyCryptodome',Crypto.__version__,'cryptography',cryptography.__version__)
open(os.path.join(os.environ['OUT'],'aes-api-help.txt'),'w').write(inspect.getdoc(AES.new))
d=json.load(open('store/jobs/j000322/out/gzip-utf-8-parsed.json'))
names={'fiatAuthKeyPair','abTestingKeyPair','exodusSharesEncryptionKeyPair','exodusSharesKeyPair'}
found={}
def walk(x):
 if isinstance(x,dict):
  for k,v in x.items():
   if k in names: found[k]=json.loads(v) if isinstance(v,str) else v
   else: walk(v)
 elif isinstance(x,list):
  for v in x: walk(v)
walk(d)
assert set(found)==names, 'expected four named pair objects'
def buf(x):
 assert isinstance(x,dict) and x.get('type')=='Buffer'
 z=x['data']; assert isinstance(z,str) and z.startswith('base64:')
 return base64.b64decode(z[7:],validate=True)
rows=[]
for name,x in sorted(found.items()):
 p,q=buf(x['privateKey']),buf(x['publicKey'])
 if x.get('keyType')=='ed25519':
  assert len(p)==64 and len(q)==32
  derived=ed25519.Ed25519PrivateKey.from_private_bytes(p[:32]).public_key().public_bytes(Encoding.Raw,PublicFormat.Raw)
  consistent=(derived==q and p[32:]==q)
 elif x.get('curve')=='x25519':
  assert len(p)==32 and len(q)==32
  derived=x25519.X25519PrivateKey.from_private_bytes(p).public_key().public_bytes(Encoding.Raw,PublicFormat.Raw)
  consistent=derived==q
 else: raise ValueError('unexpected algorithm label')
 rows.append({'field':name,'private_bytes':len(p),'public_bytes':len(q),'public_from_secret_matches':consistent,'direct_secret_bytes':32})
assert all(r['public_from_secret_matches'] for r in rows)
controls={}
for mode in (AES.MODE_CCM,AES.MODE_GCM):
 c=AES.new(b'\0'*32,mode,nonce=b'\0'*8,mac_len=4)
 ct,tag=c.encrypt_and_digest(b'local synthetic control')
 controls[str(mode)]=AES.new(b'\0'*32,mode,nonce=b'\0'*8,mac_len=4).decrypt_and_verify(ct,tag)==b'local synthetic control'
r={'versions':{'PyCryptodome':Crypto.__version__,'cryptography':cryptography.__version__},'pairs':rows,'synthetic_aead_controls':controls,'secret_values_or_hashes_emitted':False}
json.dump(r,open(os.path.join(os.environ['OUT'],'pair-consistency-and-api.json'),'w'),indent=2)
print('pairs',len(rows),'consistent',sum(v['public_from_secret_matches'] for v in rows),'control_modes',len(controls),'no secret values or hashes emitted')
PY
